<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>
<script>
let points=@json($run?->route_points ?? []),map=null,line=null;const editable=@json((bool)($run?->started_at && !$run?->finished_at));const zone=@json($zone?->coordinates ?? []);
if(typeof L!=='undefined'){map=L.map('routeMap').setView([-6.76,-79.84],13);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:19}).addTo(map);if(Array.isArray(zone)&&zone.length>=3){try{const polygon=L.polygon(zone,{color:'#94a3b8',fillOpacity:.08}).addTo(map);map.fitBounds(polygon.getBounds());}catch(e){}}line=L.polyline(points,{color:'#087dc1',weight:5}).addTo(map);if(points.length>1)map.fitBounds(line.getBounds());if(editable)map.on('click',e=>{points.push([Number(e.latlng.lat.toFixed(6)),Number(e.latlng.lng.toFixed(6))]);render();});}else document.getElementById('routeMap').textContent='No se pudo cargar el mapa. Puede consultar o registrar las coordenadas debajo.';
function render(){if(line)line.setLatLngs(points);const input=document.getElementById('route_points');if(input)input.value=JSON.stringify(points);const area=document.getElementById('routeCoordinates');if(area)area.value=JSON.stringify(points);}
if(editable){render();document.getElementById('undoPoint').onclick=()=>{points.pop();render();};document.getElementById('clearPoints').onclick=()=>{points=[];render();};document.getElementById('loadPoints').onclick=()=>{try{const value=JSON.parse(document.getElementById('routeCoordinates').value);if(!Array.isArray(value)||value.length>5000||value.some(p=>!Array.isArray(p)||p.length!==2||!p.every(Number.isFinite)||Math.abs(p[0])>90||Math.abs(p[1])>180))throw Error();points=value;render();if(line&&points.length>1)map.fitBounds(line.getBounds());document.getElementById('routeError').textContent='';}catch(e){document.getElementById('routeError').textContent='Ingrese pares válidos de latitud y longitud.';}};document.getElementById('finishRoute').onsubmit=e=>{if(points.length<2){e.preventDefault();document.getElementById('routeError').textContent='Registre al menos dos puntos del recorrido.';}else if(!confirm('¿Finalizar este recorrido y guardar el trazado registrado?'))e.preventDefault();};}
</script>
